const lectiiVechi = {
  "Mulțimi de numere și operații cu numere reale": {
    href: "/lectii/numere-reale",
    storageKey: "lectie-numere-reale-finalizata",
  },

  "Estimări și aproximări": {
    href: "/lectii/estimari-aproximari",
    storageKey: "lectie-estimari-aproximari-finalizata",
  },

  "Modulul unui număr real": {
    href: "/lectii/modul-numar-real",
    storageKey: "lectie-modul-numar-real-finalizata",
  },

  "Intervale de numere reale": {
    href: "/lectii/intervale-numere-reale",
    storageKey: "lectie-intervale-numere-reale-finalizata",
  },

  "Propoziții și predicate": {
    href: "/lectii/propozitii-predicate",
    storageKey: "lectie-propozitii-predicate-finalizata",
  },
};

export default function ProgramaPage() {
  const [profil, setProfil] = useState("M_mate-info");
  const [modulDeschis, setModulDeschis] = useState<string | null>(null);

  const [lectiiFinalizate, setLectiiFinalizate] = useState<
    Record<string, boolean>
  >({});

  useEffect(() => {
    const profilSalvat =
      localStorage.getItem("bac-mate-profil-cod") || "M_mate-info";

    setProfil(profilSalvat);

    const progres: Record<string, boolean> = {};

    Object.entries(lectiiVechi).forEach(([numeLectie, configurare]) => {
      progres[numeLectie] =
        localStorage.getItem(configurare.storageKey) === "da";
    });

    lectiiConstruite.forEach((lectie) => {
      progres[lectie.titlu] =
        localStorage.getItem(lectie.storageKeyFinalizata) === "da";
    });

    setLectiiFinalizate(progres);
  }, []);

  const totalLectii = moduleMateInfo.reduce(
    (total, modul) => total + modul.lectii.length,
    0
  );

  function progresModul(modul: Modul) {
    return modul.lectii.filter(
      (lectie) => lectiiFinalizate[lectie] === true
    ).length;
  }

  function gasesteConfigurareLectie(numeLectie: string) {
    const lectieVeche =
      lectiiVechi[numeLectie as keyof typeof lectiiVechi];

    if (lectieVeche) {
      return lectieVeche;
    }

    const lectieNoua = lectiiConstruite.find(
      (lectie) => lectie.titlu === numeLectie
    );

    if (!lectieNoua) {
      return null;
    }

    return {
      href: `/lectii/${lectieNoua.slug}`,
      storageKey: lectieNoua.storageKeyFinalizata,
    };
  }

  function esteLectiaDeblocata(
    modul: Modul,
    lectieIndex: number
  ) {
    const lectieCurenta = modul.lectii[lectieIndex];

    const configurareCurenta =
      gasesteConfigurareLectie(lectieCurenta);

    // Dacă lecția nu este încă construită, nu o putem deschide.
    if (!configurareCurenta) {
      return false;
    }

    // O lecție deja terminată rămâne mereu accesibilă pentru recapitulare.
    if (lectiiFinalizate[lectieCurenta]) {
      return true;
    }

    const modulIndex = moduleMateInfo.findIndex(
      (modulDinLista) => modulDinLista.id === modul.id
    );

    // Prima lecție din întreaga programă este disponibilă automat.
    if (modulIndex === 0 && lectieIndex === 0) {
      return true;
    }

    // Dacă nu este prima lecție din modul,
    // trebuie terminată lecția anterioară din același modul.
    if (lectieIndex > 0) {
      const lectieAnterioara =
        modul.lectii[lectieIndex - 1];

      return lectiiFinalizate[lectieAnterioara] === true;
    }

    // Dacă este prima lecție dintr-un modul ulterior,
    // trebuie terminată ultima lecție din modulul precedent.
    if (lectieIndex === 0 && modulIndex > 0) {
      const modulAnterior =
        moduleMateInfo[modulIndex - 1];

      const ultimaLectieModulAnterior =
        modulAnterior.lectii[
          modulAnterior.lectii.length - 1
        ];

      return (
        lectiiFinalizate[ultimaLectieModulAnterior] === true
      );
    }

    return false;
  }

  return (
    <main className="min-h-screen bg-slate-950 text-white">
      <header className="border-b border-slate-800">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-5">
          <a
            href="/dashboard"
            className="font-bold text-slate-300 transition hover:text-white"
          >
            ← Dashboard
          </a>

          <a href="/" className="text-xl font-black">
            BAC <span className="text-blue-500">MATE</span>
          </a>

          <div className="rounded-xl bg-blue-500/10 px-4 py-2 text-sm font-bold text-blue-400">
            {profil}
          </div>
        </div>
      </header>

      <div className="mx-auto max-w-6xl px-6 py-12">
        <section className="rounded-3xl border border-slate-800 bg-slate-900 p-8 md:p-10">
          <div className="max-w-4xl">
            <p className="text-sm font-black uppercase tracking-wider text-blue-400">
              Traseul tău pentru Bac
            </p>

            <h1 className="mt-4 text-4xl font-black md:text-5xl">
              Programa M_mate-info
            </h1>

            <p className="mt-5 text-lg leading-8 text-slate-300">
              Materia este organizată în module de învățare construite
              pe baza conținuturilor prevăzute în programa oficială de
              examen pentru Matematică M_mate-info.
            </p>
          </div>

          <div className="mt-8 grid gap-4 md:grid-cols-3">
            <div className="rounded-2xl bg-slate-950 p-5">
              <p className="text-sm text-slate-400">Module</p>
              <p className="mt-2 text-3xl font-black">
                {moduleMateInfo.length}
              </p>
            </div>

            <div className="rounded-2xl bg-slate-950 p-5">
              <p className="text-sm text-slate-400">
                Lecții planificate
              </p>

              <p className="mt-2 text-3xl font-black">
                {totalLectii}
              </p>
            </div>

            <div className="rounded-2xl bg-slate-950 p-5">
              <p className="text-sm text-slate-400">Profil</p>

              <p className="mt-2 text-xl font-black text-blue-400">
                {profil}
              </p>
            </div>
          </div>
        </section>

        <section className="mt-8 rounded-3xl border border-amber-500/20 bg-amber-500/5 p-6">
          <div className="flex gap-4">
            <div className="text-2xl">🛟</div>

            <div>
              <h2 className="font-black">
                Recuperare înainte de programă
              </h2>

              <p className="mt-2 leading-7 text-slate-300">
                Dacă evaluarea diagnostică descoperă lacune la calcule
                elementare, BAC MATE îți recomandă mai întâi lecții de
                recuperare. Acestea te ajută să înțelegi materia de Bac,
                fără să fie prezentate ca module oficiale separate ale
                programei.
              </p>

              <a
                href="/lectii/procente"
                className="mt-4 inline-block rounded-xl bg-amber-500/10 px-4 py-3 font-bold text-amber-300 transition hover:bg-amber-500/20"
              >
                Exemplu existent: Procente →
              </a>
            </div>
          </div>
        </section>

        <div className="mt-12">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Harta completă
          </p>

          <h2 className="mt-2 text-3xl font-black">
            Ce trebuie să stăpânești
          </h2>

          <p className="mt-3 max-w-3xl leading-7 text-slate-400">
            Lecțiile se deblochează treptat pe măsură ce termini traseul
            de învățare.
          </p>
        </div>

        <div className="mt-8 space-y-5">
          {moduleMateInfo.map((modul, index) => {
            const deschis = modulDeschis === modul.id;
            const finalizate = progresModul(modul);

            return (
              <section
                key={modul.id}
                className="overflow-hidden rounded-3xl border border-slate-800 bg-slate-900"
              >
                <button
                  onClick={() =>
                    setModulDeschis(
                      deschis ? null : modul.id
                    )
                  }
                  className="flex w-full items-center gap-5 p-6 text-left transition hover:bg-slate-800/40 md:p-7"
                >
                  <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-slate-950 text-2xl font-black">
                    {modul.icon}
                  </div>

                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-3">
                      <span className="text-sm font-black text-blue-400">
                        MODUL {index + 1}
                      </span>

                      <span className="rounded-full bg-slate-800 px-3 py-1 text-xs font-bold text-slate-400">
                        {modul.clasa}
                      </span>

                      <span className="rounded-full bg-slate-800 px-3 py-1 text-xs font-bold text-slate-400">
                        {modul.lectii.length} lecții
                      </span>

                      {finalizate > 0 && (
                        <span className="rounded-full bg-emerald-500/10 px-3 py-1 text-xs font-bold text-emerald-400">
                          {finalizate} finalizate
                        </span>
                      )}
                    </div>

                    <h3 className="mt-2 text-xl font-black md:text-2xl">
                      {modul.titlu}
                    </h3>

                    <p className="mt-2 leading-6 text-slate-400">
                      {modul.descriere}
                    </p>
                  </div>

                  <div className="text-2xl text-slate-400">
                    {deschis ? "−" : "+"}
                  </div>
                </button>

                {deschis && (
                  <div className="border-t border-slate-800 px-6 py-6 md:px-7">
                    <div className="mb-5 flex items-center justify-between">
                      <p className="font-black">
                        Lecțiile acestui modul
                      </p>

                      <span className="text-sm text-slate-500">
                        {finalizate}/{modul.lectii.length} finalizate
                      </span>
                    </div>

                    <div className="grid gap-3 md:grid-cols-2">
                      {modul.lectii.map(
                        (lectie, lectieIndex) => {
                          const configurare =
                            gasesteConfigurareLectie(lectie);

                          const finalizata =
                            lectiiFinalizate[lectie] === true;

                          const deblocata =
                            esteLectiaDeblocata(
                              modul,
                              lectieIndex
                            );

                          if (configurare && deblocata) {
                            return (
                              <a
                                key={lectie}
                                href={configurare.href}
                                className={`flex items-center gap-4 rounded-2xl border p-4 transition ${
                                  finalizata
                                    ? "border-emerald-500/30 bg-emerald-500/5 hover:bg-emerald-500/10"
                                    : "border-blue-500/30 bg-blue-500/5 hover:bg-blue-500/10"
                                }`}
                              >
                                <div
                                  className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl text-sm font-black ${
                                    finalizata
                                      ? "bg-emerald-500/10 text-emerald-400"
                                      : "bg-blue-500/10 text-blue-400"
                                  }`}
                                >
                                  {finalizata
                                    ? "✓"
                                    : lectieIndex + 1}
                                </div>

                                <div className="flex-1">
                                  <p className="font-semibold">
                                    {lectie}
                                  </p>

                                  <p
                                    className={`mt-1 text-xs font-bold ${
                                      finalizata
                                        ? "text-emerald-400"
                                        : "text-blue-400"
                                    }`}
                                  >
                                    {finalizata
                                      ? "Finalizată • Poți revedea lecția"
                                      : "Disponibilă • Începe lecția"}
                                  </p>
                                </div>

                                <span
                                  className={
                                    finalizata
                                      ? "text-emerald-400"
                                      : "text-blue-400"
                                  }
                                >
                                  {finalizata ? "✅" : "→"}
                                </span>
                              </a>
                            );
                          }

                          if (configurare && !deblocata) {
                            return (
                              <div
                                key={lectie}
                                className="flex items-center gap-4 rounded-2xl border border-slate-800 bg-slate-950 p-4"
                              >
                                <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-slate-900 text-sm font-black text-slate-400">
                                  {lectieIndex + 1}
                                </div>

                                <div className="flex-1">
                                  <p className="font-semibold">
                                    {lectie}
                                  </p>

                                  <p className="mt-1 text-xs text-slate-500">
                                    {lectieIndex === 0
                                      ? "Finalizează modulul anterior pentru a debloca această lecție"
                                      : "Finalizează lecția anterioară pentru a o debloca"}
                                  </p>
                                </div>

                                <span className="text-slate-600">
                                  🔒
                                </span>
                              </div>
                            );
                          }

                          return (
                            <div
                              key={lectie}
                              className="flex items-center gap-4 rounded-2xl border border-slate-800 bg-slate-950 p-4"
                            >
                              <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-slate-900 text-sm font-black text-slate-400">
                                {lectieIndex + 1}
                              </div>

                              <div className="flex-1">
                                <p className="font-semibold">
                                  {lectie}
                                </p>

                                <p className="mt-1 text-xs text-slate-500">
                                  Lecție în pregătire
                                </p>
                              </div>

                              <span className="text-slate-600">
                                🔒
                              </span>
                            </div>
                          );
                        }
                      )}
                    </div>
                  </div>
                )}
              </section>
            );
          })}
        </div>

        <section className="mt-10 rounded-3xl border border-blue-500/20 bg-blue-500/5 p-7">
          <p className="font-black text-blue-400">
            📘 Cum va funcționa BAC MATE
          </p>

          <p className="mt-3 max-w-4xl leading-7 text-slate-300">
            Nu va trebui să parcurgi mecanic toate lecțiile. Evaluarea
            diagnostică, progresul și greșelile tale vor determina ce
            trebuie să înveți, ce trebuie să repeți și când ești pregătit
            pentru exercițiile de nivel Bac.
          </p>
        </section>

        <div className="mt-8 flex flex-col gap-3 sm:flex-row">
          <a
            href="/evaluare"
            className="rounded-xl bg-blue-600 px-6 py-4 text-center font-black transition hover:bg-blue-500"
          >
            Fă evaluarea diagnostică →
          </a>

          <a
            href="/dashboard"
            className="rounded-xl border border-slate-700 px-6 py-4 text-center font-black transition hover:bg-slate-900"
          >
            Înapoi la Dashboard
          </a>
        </div>
      </div>
    </main>
  );
}